#include <optional>
#include <string>
#include <string_view>

std::optional<int> parseStrict(std::string_view text) { return std::nullopt; }

struct Leading
{
    std::optional<int> value;
    std::size_t used;
    std::string error;
};

Leading readLeadingInt(const std::string& text) { return { std::nullopt, 0, "" }; }

solution.solution.cpp:
#include <charconv>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>

std::optional<int> parseStrict(std::string_view text)
{
    if (!text.empty() && text[0] == '+')
    {
        text.remove_prefix(1);
        if (!text.empty() && text[0] == '-') return std::nullopt;
    }
    if (text.empty()) return std::nullopt;
    int value{ 0 };
    const auto [ptr, ec] { std::from_chars(text.data(), text.data() + text.size(), value) };
    if (ec != std::errc{} || ptr != text.data() + text.size()) return std::nullopt;
    return value;
}

struct Leading
{
    std::optional<int> value;
    std::size_t used;
    std::string error;
};

Leading readLeadingInt(const std::string& text)
{
    try
    {
        std::size_t used{ 0 };
        const int value{ std::stoi(text, &used) };
        return { value, used, "" };
    }
    catch (const std::invalid_argument&)
    {
        return { std::nullopt, 0, "no number" };
    }
    catch (const std::out_of_range&)
    {
        return { std::nullopt, 0, "out of range" };
    }
}

unitTests:
TEST("strict parsing accepts only a whole number") {
    CHECK(parseStrict("42") == std::optional<int>{ 42 });
    CHECK(parseStrict("-42") == std::optional<int>{ -42 });
    CHECK(parseStrict("+42") == std::optional<int>{ 42 });
    CHECK(parseStrict("007") == std::optional<int>{ 7 });
    CHECK(parseStrict("2147483647") == std::optional<int>{ 2147483647 });
    CHECK(parseStrict("-2147483648") == std::optional<int>{ -2147483647 - 1 });
}
TEST("strict parsing rejects everything else") {
    CHECK(!parseStrict("").has_value());
    CHECK(!parseStrict("+").has_value());
    CHECK(!parseStrict("-").has_value());
    CHECK(!parseStrict("+-4").has_value());
    CHECK(!parseStrict("--4").has_value());
    CHECK(!parseStrict("++4").has_value());
    CHECK(!parseStrict(" 4").has_value());
    CHECK(!parseStrict("4 ").has_value());
    CHECK(!parseStrict("4px").has_value());
    CHECK(!parseStrict("0x10").has_value());
    CHECK(!parseStrict("2147483648").has_value());
}
TEST("reading a leading number like stoi") {
    const Leading a{ readLeadingInt("  -12abc") };
    CHECK(a.value == std::optional<int>{ -12 });
    CHECK_EQ(a.used, 5u);
    CHECK_EQ(a.error, std::string(""));
    const Leading b{ readLeadingInt("+5") };
    CHECK(b.value == std::optional<int>{ 5 } && b.used == 2);
    const Leading c{ readLeadingInt("0x1A") };
    CHECK(c.value == std::optional<int>{ 0 } && c.used == 1);
    const Leading d{ readLeadingInt("\t\n 7") };
    CHECK(d.value == std::optional<int>{ 7 } && d.used == 4);
}
TEST("reporting what stoi would throw") {
    const Leading a{ readLeadingInt("abc") };
    CHECK(!a.value.has_value() && a.used == 0 && a.error == "no number");
    CHECK_EQ(readLeadingInt("").error, std::string("no number"));
    CHECK_EQ(readLeadingInt("   ").error, std::string("no number"));
    CHECK_EQ(readLeadingInt("-").error, std::string("no number"));
    const Leading big{ readLeadingInt("99999999999") };
    CHECK(!big.value.has_value() && big.used == 0 && big.error == "out of range");
}

